import time
from abc import ABC, abstractmethod

from taf.hw.optical_switch.devices.base import OpticalSwitch
from taf.hw.optical_switch.devices.clients.telnet_client import TelnetClient
from taf.hw.optical_switch.exceptions import InvalidInput, Timeout


class TelnetOpticalSwitch(OpticalSwitch, ABC):
    """Class that makes it possible to
    manage a single PDU device over the telnet."""

    def __init__(self, host, port=10001, timeout=None):
        super().__init__(host=host, port=port, timeout=timeout)
        self._encoding = "utf-8"
        self.telnet_client = TelnetClient(
            self._host, self._port, self._timeout, self._encoding
        )

    @property
    @abstractmethod
    def channel_amount(self):
        """Amount of available channels"""
        pass

    @property
    @abstractmethod
    def module_amount(self):
        """Amount of available modules"""
        pass

    def _check_if_settings_changed(self, new_settings):
        start = time.time()
        while time.time() - start < self._timeout:
            settings = self.get_optical_switch_channels()
            if all(item in settings.items() for item in new_settings.items()):
                return True
        raise Timeout("Telnet connection timed out.")

    def _check_if_modules_and_channels_in_range(self, settings):
        for module, channel in settings.items():
            if module not in range(1, self.module_amount + 1):
                error_msg = f"Given module: {module} is out of range. Module amount: {self.module_amount}"
                raise InvalidInput(error_msg)
            if channel not in range(1, self.channel_amount + 1):
                error_msg = f"Given channel: {channel} is out of range. Channel amount: {self.channel_amount}"
                raise InvalidInput(error_msg)

    def teardown(self):
        self.telnet_client.close()
        self.telnet_client = None
